  "neon.badge": "NEU · Web-App",
  "neon.title": `LumiSign <span class="neon-glow">NEON</span> — Neonschriftzüge im Browser`,
  "neon.desc": `LumiSign NEON ist eine Web-App, die eine <strong style="color:var(--text)">DXF</strong>-Kontur in einen 3D-druckbaren Kanal für <strong style="color:var(--text)">LED-Neon-Flex-Streifen</strong> verwandelt. Stellen Sie Schlitzbreite, Wand- und Bodenstärke, Kanaltiefe und optionale Rückplatte ein, fügen Sie Montage- und Kabelöffnungen hinzu, teilen Sie große Schriftzüge passend zum Druckbett — und der integrierte <strong style="color:var(--text)">Materialrechner</strong> zeigt sofort die benötigte Streifenlänge, die Anzahl der Rollen und die physische Größe des Schriftzugs. Alles in einer Echtzeit-3D-Vorschau, direkt im Browser.`,
  "neon.chips": `<span class="neon-chip">+ DXF-Import</span><span class="neon-chip">+ LED-Streifen-Routing</span><span class="neon-chip">+ Montage- &amp; Kabelöffnungen</span><span class="neon-chip">+ Druck-Aufteilung</span><span class="neon-chip">+ Materialrechner</span><span class="neon-chip">+ Echtzeit-3D-Vorschau</span><span class="neon-chip">+ STL-Export</span><span class="neon-chip">+ 11 Sprachen</span>`,

  "nav.apps": "Apps",
  "apps.label": "LumiSign3D-Familie",
  "apps.title": `Ein Toolkit — alle Apps kostenlos`,
  "apps.sub": "3D Channel Letters ist Teil der LumiSign3D-Familie — eines kompletten Werkzeugkastens für Leuchtreklame. Jede App öffnen Sie mit einem Klick direkt von ihrer Karte.",
  "apps.license": `<strong style="color:var(--text)">Alle Apps sind kostenlos.</strong> Die Desktop-App, die Web-App und alle Online-Tools unten — keine Lizenzschlüssel, keine Abos, keine Konten. Wenn sie Ihnen Zeit sparen, hilft eine <a href="#support" style="color:var(--cyan);text-decoration:none;">freiwillige Spende</a> bei der Weiterentwicklung.`,
  "apps.live": "LIVE",
  "apps.open": "Öffnen",
  "apps.a1k": "Web-App",
  "apps.a1t": "3D Channel Letters — Web",
  "apps.a1d": "Das komplette Channel-Letters-Erlebnis im Browser — DXF laden und Sie erhalten ein 3D-Modell mit Falz für das Acryl. Wände, Acryl und Rückwand konfigurieren, Farben abstimmen und für jedes Teil eine separate, druckfertige STL herunterladen.",
  "apps.a1chips": `<span class="app-chip">DXF-Import</span><span class="app-chip">Acryl-Falz</span><span class="app-chip">STL pro Objekt</span><span class="app-chip">Kostenlos</span>`,
  "apps.a2k": "Web-Tool",
  "apps.a2t": "DXF-Generator",
  "apps.a2d": "Text eingeben, Schriftart wählen und eine saubere DXF für Neonschilder und Channel Letters herunterladen. Unterstützt Einlinien- und Konturschriften, eigene TTF/OTF/WOFF, Kerning, Verschweißen überlappender Buchstaben und Bogenglättung. Export als DXF R12 in Millimetern — bereit für CNC, Laser und Biegemaschinen.",
  "apps.a2chips": `<span class="app-chip">Text → DXF</span><span class="app-chip">Eigene Schriften (TTF/OTF)</span><span class="app-chip">DXF R12 · mm</span><span class="app-chip">CNC · Laser</span>`,
  "apps.a3k": "Web-App",
  "apps.a3t": "LumiSign NEON",
  "apps.a3d": "Verwandeln Sie eine DXF oder einfachen Text in einen 3D-druckbaren Kanal für LED-Neon-Flex-Streifen. Der Materialrechner zeigt sofort Streifenlänge, Rollenanzahl und die Größe des Schildes — und teilt große Schilder in Kacheln, die auf Ihr Druckbett passen.",
  "apps.a3chips": `<span class="app-chip">Text → Neon</span><span class="app-chip">Materialrechner</span><span class="app-chip">Kachel-Aufteilung</span><span class="app-chip">STL-Export</span>`,
  "apps.a4k": "Web-Tool",
  "apps.a4t": "Gift Box Designer",
  "apps.a4d": "Entwerfen und drucken Sie Ihre eigene Geschenkbox mit wenigen Klicks. Format von A4 bis A1 wählen, Maße anpassen und einen präzisen Schneideplan herunterladen — bereit zum Ausschneiden und Falten, in fünf Sprachen.",
  "apps.a4chips": `<span class="app-chip">Formate A4–A1</span><span class="app-chip">Schneideplan</span><span class="app-chip">SK · CZ · PL · EN · DE</span>`,
  "apps.a5k": "Web-Tool",
  "apps.a5t": "Perimeters",
  "apps.a5d": "Vektor hochladen und sofort den exakten Umfang jedes Pfads erhalten — also wie viel Blech Sie für die Zargen (Seitenwände) Ihrer Leuchtbuchstaben benötigen. Kein Schätzen, kein Materialverlust.",
  "apps.a5chips": `<span class="app-chip">Vektor-Umfänge</span><span class="app-chip">Blechlänge</span><span class="app-chip">Sofortergebnis</span>`,
  "apps.a6k": "Web-App",
  "apps.a6t": "ESP32 LED Simulator",
  "apps.a6d": "Simulieren Sie adressierbare LEDs (WS2812B) direkt in Acrylbuchstaben — mit Streifenlayout, IN/OUT-Verdrahtung und live abgespielten Effekten. Der Rechner ermittelt LED-Anzahl, Streifenlänge, Strom und das nötige 5-V-Netzteil und erzeugt fertigen FastLED- / WLED-Code für ESP32.",
  "apps.a6chips": `<span class="app-chip">Live-Effekte</span><span class="app-chip">Netzteil-Rechner</span><span class="app-chip">FastLED / WLED-Code</span><span class="app-chip">Wi-Fi (ESP32)</span>`,
  "neon.btn": "NEON Web-App öffnen →",
  "neon.note": "Läuft in jedem modernen Browser — keine Installation nötig.",

  "ll.h8": `LumiSign3D-Web-Apps`,
  "ll.p8": `Dieselben Bedingungen gelten für <a href="https://neon.lumisign3d.com">LumiSign NEON</a> und alle anderen LumiSign3D-Web-Apps — alle kostenlos.`,
  "price.btn": `⬇ Kostenlos herunterladen`,

  "dl.label": "Herunterladen",
  "dl.title": "Anwendung herunterladen",
  "dl.sub": `Direkt im Browser nutzen oder für macOS und Windows herunterladen. Komplett kostenlos — kein Lizenzschlüssel, kein Konto nötig.`,
  "dl.webT": "Web-App öffnen",
  "dl.webS": "Online-App — läuft in jedem modernen Browser, keine Installation nötig",
  "dl.macT": "Für macOS herunterladen",
  "dl.macS": "Apple-signiert & notarisiert · macOS 12.0 oder neuer",
  "dl.winT": "Für Windows herunterladen",
  "dl.winS": "x64-Setup · Windows 10 / 11 · Siehe Installationshinweise unten",
  "dl.winNotesTitle": "Windows-Installationshinweise",
  "dl.winIntro": "Der Windows-Build ist noch nicht mit einem Code-Signing-Zertifikat signiert, daher warnen Windows SmartScreen und Defender beim ersten Start. Der Installer ist sicher — mit diesen Schritten entsperren Sie ihn:",
  "dl.winLi1": `<strong style="color:var(--text);">Nach dem Download</strong> entpacken Sie die ZIP-Datei, klicken Sie dann mit der rechten Maustaste auf <code style="background:rgba(82,226,255,.08);padding:2px 7px;border-radius:6px;color:var(--cyan);font-size:13px;">ChannelLetters_1.0.30_x64-setup.exe</code> → <strong style="color:var(--text);">Eigenschaften</strong> → unten <strong style="color:var(--text);">Zulassen</strong> ankreuzen → OK. Dann per Doppelklick ausführen.`,
  "dl.winLi2": `Wenn <strong style="color:var(--text);">„Der Computer wurde durch Windows geschützt“</strong> erscheint: klicken Sie auf <strong style="color:var(--text);">Weitere Informationen</strong> → <strong style="color:var(--text);">Trotzdem ausführen</strong>.`,
  "dl.winLi3": `Wenn Defender die Datei weiterhin kennzeichnet: öffnen Sie <strong style="color:var(--text);">Einstellungen → Viren- & Bedrohungsschutz → Einstellungen verwalten → Ausschlüsse hinzufügen oder entfernen</strong> und fügen Sie den Ordner hinzu, in dem Sie die App installieren.`,
  "dl.winFoot": "Ein signierter Windows-Build ist in Arbeit — diese Warnungen verschwinden, sobald das Zertifikat vorhanden ist.",
  "dl.support": `Diese App ist ein mit Sorgfalt entwickeltes Soloprojekt. Sie ist für alle kostenlos — wenn sie Ihnen bei der Arbeit hilft, bedeutet eine Spende in beliebiger Höhe sehr viel und ermöglicht es mir, die App weiter zu verbessern und neue Funktionen hinzuzufügen.`,

  "sup.label": "Unterstützung",
  "sup.title": `Projekt unterstützen`,
  "sup.sub": `3D Channel Letters und alle LumiSign3D-Apps sind kostenlos. Wenn sie Ihnen Zeit sparen oder Geld einbringen, können Sie eine freiwillige Spende in beliebiger Höhe senden — kein Konto, keine E-Mail, sonst nichts nötig.`,

  "pay.opt1": "Option 1",
